exit 0 4 GA-01 from_GA02
exit 0 5 GA-01 from_GA02
mark from_GA01 2 4 E
mark dock 33 15 E
mark crate 28 15 S
prop conveyor_ds 6 8
prop conveyor_ds 9 8
prop conveyor_ds 12 8
prop conveyor_ds 15 8
text 10 9 "분류 컨베이어. 상자가 가다 선 채로 굳었다. 송장마다 '10/24 오전 배송'." w=4
prop crate_police_ga 30 4
box 30 4 police_crate lock=50 name="경찰 납품 상자"
text 31 4 "송장. '경찰 기동대 진압복 — 여의도 지구대, 10/24 오전 수령 예정'. 받을 사람이 오지 않았다." w=1
prop returns_ga 20 5
box 20 5 returns w=2 name="반품 더미"
prop returns_ga 23 12
box 23 12 returns w=2 name="반품 더미"
prop steel_rack 34 8
box 34 8 crate w=2 name="창고 선반"
prop rat_nest_ga 5 16
text 5 17 "왕쥐 둥지. 찢은 옷감 · 솜 · 마네킹 팔 하나. 갉은 자국이 크다." w=2
prop crate_suit_ga 28 15 cond="GA_BOX == 0 or (GA_BOX == 1 and GA_BOX_DONE == 0)"
prop crate_suit_ga 28 15 state=burnt cond="GA_BOX == 2"
prop crate_suit_ga 28 15 state=swapped cond="GA_BOX == 3 and GA_BOX_DONE == 0"
prop crate_suit_ga 28 15 state=empty cond="GA_BOX == 4 or GA_BOX == 5 or (GA_BOX == 1 and GA_BOX_DONE == 1) or (GA_BOX == 3 and GA_BOX_DONE == 1)"
box 28 15 suit_crate name="작업복 상자" cond="GA_BOX == 0"
text 29 15 "꼬리표. '새벽인력 인솔조 — 사흘째 아침 수거'. 못이 반쯤 뽑혀 있다." scene=GA_CRATE cond="GA_BOX == 0"
prop drum 26 16
text 26 17 "기름통. 반쯤 찼다. 냄새가 독하다." w=1
prop w_shutter_big 33 1
text 34 3 "하역장 셔터. 아래가 반 뼘 들렸다. 밖에서 손수레 바퀴 자국이 들어와 있다." w=2 scene=GA_DOCKIN
mark from_dock 34 4 S
prop cart_ga 31 4 cond="GA_BOX != 6"
prop cart_ga 31 4 state=blood cond="GA_BOX == 6"
text 31 5 "하역장 손수레. 바퀴에 분필 가루." w=1 cond="GA_BOX != 6"
text 31 5 "뒤집힌 손수레. 바닥에 끈적한 자국이 셔터 쪽으로 끌려갔다. 탄피 몇 개." w=1 cond="GA_BOX == 6"
prop pallet_sacks 36 17
prop pallet_sacks 15 19
prop crate_o 19 19
box 19 19 crate name="깨진 납품 상자"
prop returns_ga 13 18
text 17 19 "손수레 바퀴 자국이 하역장에서 여기까지 왔다가 되돌아갔다. 쥐 둥지 쪽은 피해서." w=2
prop crate_o 37 12
box 37 12 crate name="하역장 상자"
# ---------------------------------------------------------------- 인솔조(새벽인력 우세 · 낮) — 바크만
npc N-GA-S1 33 15 W look=M2-S4-HR01-H1-T05-1-PF12-HD05-EY00 cond="((PDO_R01_6 == \"SB\" and PDS_R01_6 >= 2) or GA_PICK == GAME_DAY) and GAME_HOUR >= 6 and GAME_HOUR < 18 and not (dead(\"C-013\") == 1 and dead(\"C-049\") == 1) and GA_BOX == 0 and GA_SIDE != 2" bark="오늘 실을 상자. 벌수 맞나 세어 봐."
npc N-GA-S1 33 15 W look=M2-S4-HR01-H1-T05-1-PF12-HD05-EY00 cond="((PDO_R01_6 == \"SB\" and PDS_R01_6 >= 2) or GA_PICK == GAME_DAY) and GAME_HOUR >= 6 and GAME_HOUR < 18 and not (dead(\"C-013\") == 1 and dead(\"C-049\") == 1) and GA_BOX == 0 and GA_SIDE == 2" bark="오늘 뭔가 이상해. 위층이 너무 조용해."
npc N-GA-S2 34 16 W look=M1-S3-HR02-H1-T05-1-PF12-HD02-EY00 cond="((PDO_R01_6 == \"SB\" and PDS_R01_6 >= 2) or GA_PICK == GAME_DAY) and GAME_HOUR >= 6 and GAME_HOUR < 18 and not (dead(\"C-013\") == 1 and dead(\"C-049\") == 1) and GA_BOX == 0" bark="인력들 입힐 거야. 맞는 치수로."
npc N-GA-S1 33 15 W look=M2-S4-HR01-H1-T05-1-PF12-HD05-EY00 cond="((PDO_R01_6 == \"SB\" and PDS_R01_6 >= 2) or GA_PICK == GAME_DAY) and GAME_HOUR >= 6 and GAME_HOUR < 18 and not (dead(\"C-013\") == 1 and dead(\"C-049\") == 1) and GA_BOX == 1" bark="동그라미 안에 딱 있네. 누군지 몰라도 손이 빠르군."
npc N-GA-S2 34 16 W look=M1-S3-HR02-H1-T05-1-PF12-HD02-EY00 cond="((PDO_R01_6 == \"SB\" and PDS_R01_6 >= 2) or GA_PICK == GAME_DAY) and GAME_HOUR >= 6 and GAME_HOUR < 18 and not (dead(\"C-013\") == 1 and dead(\"C-049\") == 1) and GA_BOX == 1" bark="벌당 5캡 봉투는 저기 두고 간다. 주인이 찾아가겠지."
npc N-GA-S1 33 15 W look=M2-S4-HR01-H1-T05-1-PF12-HD05-EY00 cond="((PDO_R01_6 == \"SB\" and PDS_R01_6 >= 2) or GA_PICK == GAME_DAY) and GAME_HOUR >= 6 and GAME_HOUR < 18 and not (dead(\"C-013\") == 1 and dead(\"C-049\") == 1) and GA_BOX == 2" bark="…다 탔잖아. 패거리 놈들, 불장난을 해?"
npc N-GA-S2 34 16 W look=M1-S3-HR02-H1-T05-1-PF12-HD02-EY00 cond="((PDO_R01_6 == \"SB\" and PDS_R01_6 >= 2) or GA_PICK == GAME_DAY) and GAME_HOUR >= 6 and GAME_HOUR < 18 and not (dead(\"C-013\") == 1 and dead(\"C-049\") == 1) and GA_BOX == 2" bark="재 냄새. 인력들 맨몸으로 내보내게 생겼다."
npc N-GA-S1 33 15 W look=M2-S4-HR01-H1-T05-1-PF12-HD05-EY00 cond="((PDO_R01_6 == \"SB\" and PDS_R01_6 >= 2) or GA_PICK == GAME_DAY) and GAME_HOUR >= 6 and GAME_HOUR < 18 and not (dead(\"C-013\") == 1 and dead(\"C-049\") == 1) and GA_BOX == 3" bark="…우비? 이게 작업복이야? 패거리 놈들, 셈을 해 보자 이거지."
npc N-GA-S2 34 16 W look=M1-S3-HR02-H1-T05-1-PF12-HD02-EY00 cond="((PDO_R01_6 == \"SB\" and PDS_R01_6 >= 2) or GA_PICK == GAME_DAY) and GAME_HOUR >= 6 and GAME_HOUR < 18 and not (dead(\"C-013\") == 1 and dead(\"C-049\") == 1) and GA_BOX == 3" bark="노란 거라도 입혀. 비는 막겠지."
npc N-GA-S1 33 15 W look=M2-S4-HR01-H1-T05-1-PF12-HD05-EY00 cond="((PDO_R01_6 == \"SB\" and PDS_R01_6 >= 2) or GA_PICK == GAME_DAY) and GAME_HOUR >= 6 and GAME_HOUR < 18 and not (dead(\"C-013\") == 1 and dead(\"C-049\") == 1) and GA_BOX == 4" bark="목요일 건 실었다. 다음 건 언제냐."
npc N-GA-S2 34 16 W look=M1-S3-HR02-H1-T05-1-PF12-HD02-EY00 cond="((PDO_R01_6 == \"SB\" and PDS_R01_6 >= 2) or GA_PICK == GAME_DAY) and GAME_HOUR >= 6 and GAME_HOUR < 18 and not (dead(\"C-013\") == 1 and dead(\"C-049\") == 1) and GA_BOX == 4" bark="패거리한테 벌당 5캡. 싸게 먹혔어."
npc N-GA-S1 33 15 W look=M2-S4-HR01-H1-T05-1-PF12-HD05-EY00 cond="((PDO_R01_6 == \"SB\" and PDS_R01_6 >= 2) or GA_PICK == GAME_DAY) and GAME_HOUR >= 6 and GAME_HOUR < 18 and not (dead(\"C-013\") == 1 and dead(\"C-049\") == 1) and GA_BOX == 5" bark="빈 상자? 벌수가 하나도 없어. 패거리가 우릴 갖고 놀아."
npc N-GA-S2 34 16 W look=M1-S3-HR02-H1-T05-1-PF12-HD02-EY00 cond="((PDO_R01_6 == \"SB\" and PDS_R01_6 >= 2) or GA_PICK == GAME_DAY) and GAME_HOUR >= 6 and GAME_HOUR < 18 and not (dead(\"C-013\") == 1 and dead(\"C-049\") == 1) and GA_BOX == 5" bark="못 자국 봐. 안에서 빼 간 거야."
